/**
  ******************************************************************************
  * @file           : main.c
  * @brief          : MQ-3 TinyML Anomaly Detector — FreeRTOS
  *
  * Target : STM32F411 (HSI @ 100 MHz)
  * Pins   : PA0 → AO (analog in, ADC1 CH0)
  *          PA8 → DO (digital in, MQ-3 onboard comparator output)
  * Serial : USART2, 115200 8N1
  *
  * AI model : mq3_autoencoder — INT8 quantised, generated by X-Cube-AI
  *   Input  : 8 × float32
  *   Output : 8 × float32 (dequantised)
  *
  * Serial output format:  ADC:<raw>  MSE:<value>  AI:<OK|ANOMALY>  DO:<LOW|HIGH>
  *
  * Threshold calibration:
  *   ANOMALY_THRESHOLD starts at 0.01f.  Watch MSE in clean air ~1 min,
  *   then set to ~3x the highest clean-air MSE you observe.
  ******************************************************************************
  */
/* USER CODE END Header */

