/* USER CODE BEGIN Header_StartDefaultTask */
/**
  * @brief  Main sensor + inference loop, runs as the FreeRTOS default task.
  */
/* USER CODE END Header_StartDefaultTask */
void StartDefaultTask(void *argument)
{
  /* USER CODE BEGIN 5 */
  for (;;)
  {
    /* ── Step 1: Sample ADC into circular buffer ──────────────────────── */
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);
    adc_buf[buf_head % WINDOW_SIZE] = (uint16_t)HAL_ADC_GetValue(&hadc1);
    buf_head++;

    /* Wait until buffer fully populated to avoid zero-pad MSE */
    if (buf_head < WINDOW_SIZE)
    {
      osDelay(100);
      continue;
    }

    if (!buf_ready)
    {
      buf_ready = 1;
      const char *rdy = "Buffer full — inference active\r\n";
      HAL_UART_Transmit(&huart2, (uint8_t *)rdy, strlen(rdy), HAL_MAX_DELAY);
    }

    /* ── Step 2: Build 8-element feature vector ───────────────────────
     *   [0..3]  last 4 normalised readings, newest first
     *   [4]     window mean
     *   [5]     window max
     *   [6]     window min
     *   [7]     delta = newest - oldest
     * After buf_head++, (buf_head % WINDOW_SIZE) is the OLDEST slot.  */
    float features[WINDOW_SIZE];
    float recon[WINDOW_SIZE];

    features[0] = adc_buf[(buf_head - 1u) % WINDOW_SIZE] / ADC_MAX;
    features[1] = adc_buf[(buf_head - 2u) % WINDOW_SIZE] / ADC_MAX;
    features[2] = adc_buf[(buf_head - 3u) % WINDOW_SIZE] / ADC_MAX;
    features[3] = adc_buf[(buf_head - 4u) % WINDOW_SIZE] / ADC_MAX;

    float sum = 0.0f, mx = 0.0f, mn = 1.0f;
    for (int i = 0; i < WINDOW_SIZE; i++)
    {
      float v = adc_buf[i] / ADC_MAX;
      sum += v;
      if (v > mx) mx = v;
      if (v < mn) mn = v;
    }
    features[4] = sum / (float)WINDOW_SIZE;
    features[5] = mx;
    features[6] = mn;
    features[7] = features[0] - (adc_buf[buf_head % WINDOW_SIZE] / ADC_MAX);

    /* ── Step 3: Run AI inference ─────────────────────────────────────── */
    ai_buffer *ai_input  = ai_network_inputs_get(network, NULL);
    ai_buffer *ai_output = ai_network_outputs_get(network, NULL);
    ai_input->data  = AI_HANDLE_PTR(features);
    ai_output->data = AI_HANDLE_PTR(recon);

    ai_i32 n_batch = ai_network_run(network, ai_input, ai_output);
    if (n_batch <= 0)
    {
      ai_error err = ai_network_get_error(network);
      char errmsg[64];
      int  elen = snprintf(errmsg, sizeof(errmsg),
                           "AI ERR type:%d code:%d\r\n", err.type, err.code);
      HAL_UART_Transmit(&huart2, (uint8_t *)errmsg, (uint16_t)elen, HAL_MAX_DELAY);
      osDelay(100);
      continue;
    }

    /* ── Step 4: Compute MSE reconstruction error ─────────────────────
     * X-Cube-AI dequantises INT8 output to float32, so recon[] is in
     * the same [0,1] space as features[].                              */
    float mse = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++)
    {
      float diff = features[i] - recon[i];
      mse += diff * diff;
    }
    mse /= (float)WINDOW_SIZE;

    /* ── Step 5: Read DO pin (PA8) ────────────────────────────────────── */
    GPIO_PinState do_pin = HAL_GPIO_ReadPin(D0_GPIO_Port, D0_Pin);

    /* ── Step 6: UART log ─────────────────────────────────────────────── */
    char msg[96];
    int  len = snprintf(msg, sizeof(msg),
                        "ADC:%4u  MSE:%.6f  AI:%s  DO:%s\r\n",
                        adc_buf[(buf_head - 1u) % WINDOW_SIZE],
                        (double)mse,
                        (mse > ANOMALY_THRESHOLD) ? "ANOMALY" : "OK",
                        (do_pin == GPIO_PIN_SET)   ? "HIGH"    : "LOW");
    HAL_UART_Transmit(&huart2, (uint8_t *)msg, (uint16_t)len, HAL_MAX_DELAY);

    /* ── Step 7: 100 ms sample period ────────────────────────────────── */
    osDelay(100);
  }
  /* USER CODE END 5 */
}

